"""Command-line entry point. Owned by the parent; workers do not edit this file."""

from __future__ import annotations

import argparse
import json
import sys

from unifi_carto import __version__
from unifi_carto.model import json_schema


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="unifi-carto", description=__doc__)
    parser.add_argument("--version", action="version", version=f"%(prog)s {__version__}")
    sub = parser.add_subparsers(dest="command", required=True)
    sub.add_parser("schema", help="print the inventory JSON Schema")
    args = parser.parse_args(argv)
    if args.command == "schema":
        json.dump(json_schema(), sys.stdout, indent=2, sort_keys=True)
        sys.stdout.write("\n")
        return 0
    return 2  # pragma: no cover - argparse enforces the choices


if __name__ == "__main__":
    raise SystemExit(main())
